CREATE DATABASE IF NOT EXISTS leave_monitor CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE leave_monitor;
CREATE TABLE schools(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,status ENUM('pending','active','rejected','suspended') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,school_id BIGINT UNSIGNED NULL,name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('platform_admin','school_admin','teacher','student') NOT NULL,avatar_path VARCHAR(255),active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(school_id) REFERENCES schools(id) ON DELETE CASCADE,INDEX(school_id,role)) ENGINE=InnoDB;
CREATE TABLE academic_years(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,school_id BIGINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,start_date DATE,end_date DATE,is_current TINYINT(1) DEFAULT 0,FOREIGN KEY(school_id) REFERENCES schools(id) ON DELETE CASCADE,UNIQUE(school_id,name)) ENGINE=InnoDB;
CREATE TABLE sections(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,school_id BIGINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,academic_year_id BIGINT UNSIGNED,FOREIGN KEY(school_id) REFERENCES schools(id) ON DELETE CASCADE,FOREIGN KEY(academic_year_id) REFERENCES academic_years(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE teachers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,school_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL UNIQUE,employee_no VARCHAR(80),FOREIGN KEY(school_id) REFERENCES schools(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE students(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,school_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL UNIQUE,student_no VARCHAR(80),FOREIGN KEY(school_id) REFERENCES schools(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE enrollments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,school_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,section_id BIGINT UNSIGNED NOT NULL,academic_year_id BIGINT UNSIGNED NOT NULL,FOREIGN KEY(school_id) REFERENCES schools(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(section_id) REFERENCES sections(id) ON DELETE CASCADE,FOREIGN KEY(academic_year_id) REFERENCES academic_years(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE attendance_records(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,school_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,attendance_date DATE NOT NULL,status ENUM('present','absent','leave','holiday') NOT NULL DEFAULT 'present',time_in TIME NULL,time_out TIME NULL,remarks VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(school_id) REFERENCES schools(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,UNIQUE KEY uq_attendance_person_day(school_id,user_id,attendance_date),INDEX idx_attendance_school_day(school_id,attendance_date)) ENGINE=InnoDB;
CREATE TABLE leave_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,school_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,reason TEXT NOT NULL,status ENUM('pending','approved','rejected') DEFAULT 'pending',admin_remark TEXT,reviewed_by BIGINT UNSIGNED,reviewed_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(school_id) REFERENCES schools(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE SET NULL,INDEX(school_id,status),INDEX(school_id,start_date,end_date)) ENGINE=InnoDB;
CREATE TABLE leave_approvals(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,leave_id BIGINT UNSIGNED NOT NULL,school_id BIGINT UNSIGNED NOT NULL,reviewer_id BIGINT UNSIGNED NOT NULL,decision ENUM('approved','rejected') NOT NULL,remark TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(leave_id) REFERENCES leave_requests(id) ON DELETE CASCADE,FOREIGN KEY(school_id) REFERENCES schools(id) ON DELETE CASCADE,FOREIGN KEY(reviewer_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE leave_attachments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,leave_id BIGINT UNSIGNED NOT NULL,school_id BIGINT UNSIGNED NOT NULL,file_path VARCHAR(255) NOT NULL,original_name VARCHAR(255) NOT NULL,FOREIGN KEY(leave_id) REFERENCES leave_requests(id) ON DELETE CASCADE,FOREIGN KEY(school_id) REFERENCES schools(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE feedback(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,school_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,category ENUM('Suggestion','General Feedback','Concern','Other') DEFAULT 'General Feedback',subject VARCHAR(190) NOT NULL,message TEXT NOT NULL,status ENUM('new','in_progress','resolved') DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(school_id) REFERENCES schools(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(school_id,status)) ENGINE=InnoDB;
CREATE TABLE feedback_responses(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,feedback_id BIGINT UNSIGNED NOT NULL,school_id BIGINT UNSIGNED NOT NULL,responder_id BIGINT UNSIGNED NOT NULL,response TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(feedback_id) REFERENCES feedback(id) ON DELETE CASCADE,FOREIGN KEY(school_id) REFERENCES schools(id) ON DELETE CASCADE,FOREIGN KEY(responder_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE feedback_attachments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,feedback_id BIGINT UNSIGNED NOT NULL,school_id BIGINT UNSIGNED NOT NULL,file_path VARCHAR(255) NOT NULL,original_name VARCHAR(255) NOT NULL,FOREIGN KEY(feedback_id) REFERENCES feedback(id) ON DELETE CASCADE,FOREIGN KEY(school_id) REFERENCES schools(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,school_id BIGINT UNSIGNED NOT NULL,message VARCHAR(500) NOT NULL,read_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(school_id) REFERENCES schools(id) ON DELETE CASCADE,INDEX(user_id,created_at)) ENGINE=InnoDB;
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,school_id BIGINT UNSIGNED NULL,user_id BIGINT UNSIGNED NULL,action VARCHAR(120) NOT NULL,record_type VARCHAR(80),record_id BIGINT UNSIGNED,ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(school_id) REFERENCES schools(id) ON DELETE SET NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,INDEX(school_id,created_at)) ENGINE=InnoDB;
CREATE TABLE login_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ip_address VARCHAR(45) NOT NULL,attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(ip_address,attempted_at)) ENGINE=InnoDB;
